-- T12: observed source events, reviewed attribution and additive reporting.
grant create on schema api,app_private to git_tutor_commands;
create table app_private.lead_inquiries(id uuid primary key default gen_random_uuid(),source text not null check(source in('website_booking','support','whatsapp')),source_event_id uuid not null,conversation_id uuid references app_private.conversations(id),actor_account_id uuid references app_private.accounts(id),observed_at timestamptz not null check(isfinite(observed_at)),recorded_at timestamptz not null default now(),observed_source_token text check(length(observed_source_token)<=500),unique(source,source_event_id));
create table app_private.learner_links(inquiry_id uuid not null references app_private.lead_inquiries(id),learner_id uuid not null references app_private.learners(id),basis text not null check(basis in('booking_relationship','authenticated_self','verified_support_link','admin_evidence')),evidence_file_id uuid references app_private.files(id),actor_id uuid references app_private.accounts(id),reason text,created_at timestamptz not null default now(),primary key(inquiry_id,learner_id));
create index analytics_learner_events on app_private.learner_links(learner_id,inquiry_id);
create table app_private.campaigns(id uuid primary key default gen_random_uuid(),source text not null,external_campaign_id text not null,name text not null,active_from date not null,active_to date not null check(active_to>=active_from),actor_id uuid not null references app_private.accounts(id),created_at timestamptz not null default now(),unique(source,external_campaign_id));
create table app_private.attribution_revisions(id uuid primary key default gen_random_uuid(),inquiry_id uuid not null references app_private.lead_inquiries(id),version integer not null,attribution text not null check(attribution in('unknown','verified_organic','verified_campaign')),campaign_id uuid references app_private.campaigns(id),evidence_file_id uuid references app_private.files(id),reason text not null,actor_id uuid not null references app_private.accounts(id),created_at timestamptz not null default now(),unique(inquiry_id,version),check((attribution='verified_campaign')=(campaign_id is not null)),check(attribution='unknown' or evidence_file_id is not null));
create table app_private.learner_history_reviews(id uuid primary key default gen_random_uuid(),learner_id uuid not null references app_private.learners(id),version integer not null,history_complete boolean not null,evidence_file_id uuid not null references app_private.files(id),reason text not null,actor_id uuid not null references app_private.accounts(id),created_at timestamptz not null default now(),unique(learner_id,version));
create table app_private.learner_attribution_revisions(id uuid primary key default gen_random_uuid(),learner_id uuid not null references app_private.learners(id),first_inquiry_id uuid not null references app_private.lead_inquiries(id),attribution text not null,campaign_id uuid references app_private.campaigns(id),previous_revision_id uuid references app_private.learner_attribution_revisions(id),policy_version text not null default 'first_eligible_v1',created_at timestamptz not null default now());
create table app_private.campaign_spend_entries(id uuid primary key default gen_random_uuid(),campaign_id uuid not null references app_private.campaigns(id),from_date date not null,to_date date not null check(to_date>=from_date),amount_minor bigint not null check(amount_minor between 0 and 9007199254740991),currency text not null check(currency='EGP'),evidence_file_id uuid not null references app_private.files(id),expense_id uuid unique references finance_private.expenses(id),actor_id uuid not null references app_private.accounts(id),created_at timestamptz not null default now());
create table app_private.campaign_spend_revisions(id uuid primary key default gen_random_uuid(),spend_entry_id uuid not null references app_private.campaign_spend_entries(id),version integer not null,amount_minor bigint not null check(amount_minor between 0 and 9007199254740991),evidence_file_id uuid not null references app_private.files(id),reason text not null,actor_id uuid not null references app_private.accounts(id),created_at timestamptz not null default now(),unique(spend_entry_id,version));
create table app_private.analytics_export_audits(id uuid primary key default gen_random_uuid(),actor_id uuid not null references app_private.accounts(id),filters jsonb not null,row_count integer not null,newly_taught_count integer not null,created_at timestamptz not null default now());

create function app_private.analytics_refresh_attribution(p_learner uuid)returns void language plpgsql security definer set search_path='' as $$declare winner record;previous app_private.learner_attribution_revisions%rowtype;begin
 perform 1 from app_private.learners where id=p_learner for update;
 select i.id,coalesce(r.attribution,'unknown')attribution,r.campaign_id into winner from app_private.learner_links l join app_private.lead_inquiries i on i.id=l.inquiry_id left join lateral(select a.attribution,a.campaign_id from app_private.attribution_revisions a where a.inquiry_id=i.id order by a.version desc limit 1)r on true where l.learner_id=p_learner order by i.observed_at,i.id limit 1;
 if winner.id is null then return;end if;
 select * into previous from app_private.learner_attribution_revisions where learner_id=p_learner order by created_at desc,id desc limit 1;
 if previous.id is null or(previous.first_inquiry_id,previous.attribution,previous.campaign_id)is distinct from(winner.id,winner.attribution,winner.campaign_id)then insert into app_private.learner_attribution_revisions(learner_id,first_inquiry_id,attribution,campaign_id,previous_revision_id)values(p_learner,winner.id,winner.attribution,winner.campaign_id,previous.id);end if;
end$$;

create function app_private.analytics_link_refresh()returns trigger language plpgsql security definer set search_path='' as $$begin perform app_private.analytics_refresh_attribution(new.learner_id);return new;end$$;
create trigger analytics_link_refresh after insert on app_private.learner_links for each row execute function app_private.analytics_link_refresh();
create function app_private.analytics_record_inquiry(p_source text,p_event uuid,p_conversation uuid,p_actor uuid,p_at timestamptz,p_token text,p_learner uuid default null)returns uuid language plpgsql security definer set search_path='' as $$declare inquiry uuid;begin
 if p_source not in('website_booking','support','whatsapp')or p_at is null or not isfinite(p_at)or p_at>now()+interval'5 seconds' then raise exception'VALIDATION_ERROR';end if;
 insert into app_private.lead_inquiries(source,source_event_id,conversation_id,actor_account_id,observed_at,observed_source_token)values(p_source,p_event,p_conversation,p_actor,p_at,p_token)on conflict(source,source_event_id)do nothing returning id into inquiry;
 if inquiry is null then select id into inquiry from app_private.lead_inquiries where source=p_source and source_event_id=p_event;end if;
 if p_learner is not null then insert into app_private.learner_links(inquiry_id,learner_id,basis,actor_id)values(inquiry,p_learner,case when p_source='website_booking'then'booking_relationship'else'authenticated_self'end,p_actor)on conflict do nothing;end if;return inquiry;
end$$;
create function app_private.analytics_source_hook()returns trigger language plpgsql security definer set search_path='' as $$declare c app_private.conversations%rowtype;l uuid;inquiry uuid;begin
 if tg_table_name='enrollments'then perform app_private.analytics_record_inquiry('website_booking',new.id,null,new.booker_account_id,new.created_at,null,new.learner_id);
 elsif tg_table_name='support_messages'then
  if new.author<>'customer'then return new;end if;select * into c from app_private.conversations where id=new.conversation_id;
  select id into l from app_private.learners where account_id=c.account_id;
  inquiry:=app_private.analytics_record_inquiry(case when c.channel='whatsapp'then'whatsapp'else'support'end,new.id,c.id,c.account_id,new.created_at,c.source_token,l);
  insert into app_private.learner_links(inquiry_id,learner_id,basis,actor_id)select inquiry,s.learner_id,'verified_support_link',s.account_id from app_private.support_account_links s where s.conversation_id=c.id and s.learner_id is not null on conflict do nothing;
 elsif tg_table_name='support_account_links'then
  if new.learner_id is not null then insert into app_private.learner_links(inquiry_id,learner_id,basis,actor_id)select i.id,new.learner_id,'verified_support_link',new.account_id from app_private.lead_inquiries i where i.conversation_id=new.conversation_id on conflict do nothing;end if;
 end if;return new;
end$$;
create trigger analytics_booking_intent after insert on app_private.enrollments for each row execute function app_private.analytics_source_hook();
create trigger analytics_support_inquiry after insert on app_private.support_messages for each row execute function app_private.analytics_source_hook();
create trigger analytics_support_link after insert on app_private.support_account_links for each row execute function app_private.analytics_source_hook();

create function api.analytics_command(p_name text,p_input jsonb,p_idempotency_key text)returns jsonb language plpgsql security definer set search_path='' as $$
declare actor uuid:=app_private.require_actor();ctx jsonb;resource uuid;v integer:=1;expected integer;allowed text[];inquiry app_private.lead_inquiries%rowtype;campaign app_private.campaigns%rowtype;spend app_private.campaign_spend_entries%rowtype;row record;amount bigint;evidence uuid;from_day date;to_day date;begin
 perform app_private.require_role(actor,'admin');
 allowed:=case p_name when'create_campaign'then array['source','external_campaign_id','name','active_from','active_to'] when'review_attribution'then array['inquiry_id','attribution','campaign_id','evidence_file_id','reason','expected_version'] when'link_inquiry_learner'then array['inquiry_id','learner_id','evidence_file_id','reason'] when'record_learner_history'then array['learner_id','history_complete','evidence_file_id','reason','expected_version'] when'record_campaign_spend'then array['campaign_id','from','to','amount_minor','currency','evidence_file_id','expense_id'] when'correct_campaign_spend'then array['spend_entry_id','amount_minor','reason','evidence_file_id','expected_version']else null end;
 if allowed is null or jsonb_typeof(p_input)is distinct from'object'or p_input-allowed<>'{}'or not(p_input?&allowed)then raise exception'VALIDATION_ERROR';end if;
 ctx:=app_private.booking_begin(actor,p_name,p_input,p_idempotency_key);if ctx->'replay_result'<>'null'::jsonb then return ctx->'replay_result';end if;
 if p_input?'reason'and(p_input->>'reason'is null or length(btrim(p_input->>'reason'))not between 1 and 2000)then raise exception'VALIDATION_ERROR';end if;
 if p_input?'expected_version'then if jsonb_typeof(p_input->'expected_version')<>'number'or(p_input->>'expected_version')!~'^[1-9][0-9]{0,8}$'then raise exception'VALIDATION_ERROR';end if;expected:=(p_input->>'expected_version')::integer;end if;
 if p_input?'evidence_file_id'and p_input->>'evidence_file_id'is not null then evidence:=(p_input->>'evidence_file_id')::uuid;perform app_private.payment_assert_file(evidence,'analytics_evidence','analytics',null,actor);end if;
 if p_name<>'create_campaign'and not(p_name='review_attribution'and p_input->>'attribution'='unknown')and evidence is null then raise exception'VALIDATION_ERROR';end if;
 if p_name='create_campaign'then
  if p_input->>'source'is null or length(btrim(p_input->>'source'))not between 1 and 100 or p_input->>'external_campaign_id'is null or length(btrim(p_input->>'external_campaign_id'))not between 1 and 200 or p_input->>'name'is null or length(btrim(p_input->>'name'))not between 1 and 200 then raise exception'VALIDATION_ERROR';end if;
  from_day:=(p_input->>'active_from')::date;to_day:=(p_input->>'active_to')::date;if from_day is null or to_day is null or not isfinite(from_day)or not isfinite(to_day)or to_day<from_day then raise exception'INVALID_TIME';end if;
  insert into app_private.campaigns(source,external_campaign_id,name,active_from,active_to,actor_id)values(btrim(p_input->>'source'),btrim(p_input->>'external_campaign_id'),btrim(p_input->>'name'),from_day,to_day,actor)returning id into resource;
 elsif p_name in('review_attribution','link_inquiry_learner')then
  perform pg_advisory_xact_lock(hashtextextended('analytics-inquiry:'||(p_input->>'inquiry_id'),0));select * into inquiry from app_private.lead_inquiries where id=(p_input->>'inquiry_id')::uuid;if inquiry.id is null then raise exception'NOT_FOUND';end if;resource:=inquiry.id;
  if p_name='review_attribution'then
   select coalesce(max(version),1)into v from app_private.attribution_revisions where inquiry_id=inquiry.id;if expected is distinct from v then raise exception'VERSION_CONFLICT';end if;
   if p_input->>'attribution'is null or p_input->>'attribution'not in('unknown','verified_organic','verified_campaign')or((p_input->>'attribution'='verified_campaign')<>(p_input->>'campaign_id'is not null))then raise exception'VALIDATION_ERROR';end if;
   if p_input->>'campaign_id'is not null then select * into campaign from app_private.campaigns where id=(p_input->>'campaign_id')::uuid;if campaign.id is null or(inquiry.observed_at at time zone'Africa/Cairo')::date not between campaign.active_from and campaign.active_to then raise exception'STATE_CONFLICT';end if;end if;
   v:=v+1;insert into app_private.attribution_revisions(inquiry_id,version,attribution,campaign_id,evidence_file_id,reason,actor_id)values(inquiry.id,v,p_input->>'attribution',campaign.id,evidence,p_input->>'reason',actor);
   for row in select learner_id from app_private.learner_links where inquiry_id=inquiry.id loop perform app_private.analytics_refresh_attribution(row.learner_id);end loop;
  else
   if not exists(select 1 from app_private.learners where id=(p_input->>'learner_id')::uuid)then raise exception'NOT_FOUND';end if;
   insert into app_private.learner_links(inquiry_id,learner_id,basis,evidence_file_id,actor_id,reason)values(inquiry.id,(p_input->>'learner_id')::uuid,'admin_evidence',evidence,actor,p_input->>'reason')on conflict do nothing;
  end if;
 elsif p_name='record_learner_history'then
  resource:=(p_input->>'learner_id')::uuid;perform 1 from app_private.learners where id=resource for update;if not found then raise exception'NOT_FOUND';end if;
  if jsonb_typeof(p_input->'history_complete')is distinct from'boolean'then raise exception'VALIDATION_ERROR';end if;select coalesce(max(version),1)into v from app_private.learner_history_reviews where learner_id=resource;if expected is distinct from v then raise exception'VERSION_CONFLICT';end if;v:=v+1;
  insert into app_private.learner_history_reviews(learner_id,version,history_complete,evidence_file_id,reason,actor_id)values(resource,v,(p_input->>'history_complete')::boolean,evidence,p_input->>'reason',actor);
 else
  if jsonb_typeof(p_input->'amount_minor')is distinct from'number'or(p_input->>'amount_minor')!~'^[0-9]+$'or(p_input->>'amount_minor')::numeric>9007199254740991 then raise exception'VALIDATION_ERROR';end if;amount:=(p_input->>'amount_minor')::bigint;
  if p_name='record_campaign_spend'then
   perform pg_advisory_xact_lock(hashtextextended('analytics-campaign:'||(p_input->>'campaign_id'),0));select * into campaign from app_private.campaigns where id=(p_input->>'campaign_id')::uuid;if campaign.id is null then raise exception'NOT_FOUND';end if;
   from_day:=(p_input->>'from')::date;to_day:=(p_input->>'to')::date;if from_day is null or to_day is null or not isfinite(from_day)or not isfinite(to_day)or to_day<from_day or from_day<campaign.active_from or to_day>campaign.active_to or p_input->>'currency'is distinct from'EGP'then raise exception'VALIDATION_ERROR';end if;
   if exists(select 1 from app_private.campaign_spend_entries s where s.campaign_id=campaign.id and daterange(s.from_date,s.to_date,'[]')&&daterange(from_day,to_day,'[]'))then raise exception'STATE_CONFLICT';end if;
   if p_input->>'expense_id'is not null then perform pg_advisory_xact_lock(hashtextextended('analytics-expense:'||(p_input->>'expense_id'),0));perform 1 from finance_private.expenses e where e.id=(p_input->>'expense_id')::uuid and e.currency='EGP'and e.category='marketing'and amount<=e.amount_minor;if not found then raise exception'VALIDATION_ERROR';end if;if exists(select 1 from app_private.campaign_spend_entries where expense_id=(p_input->>'expense_id')::uuid)then raise exception'STATE_CONFLICT';end if;end if;
   insert into app_private.campaign_spend_entries(campaign_id,from_date,to_date,amount_minor,currency,evidence_file_id,expense_id,actor_id)values(campaign.id,from_day,to_day,amount,'EGP',evidence,(p_input->>'expense_id')::uuid,actor)returning id into resource;
  else
   perform pg_advisory_xact_lock(hashtextextended('analytics-spend:'||(p_input->>'spend_entry_id'),0));select * into spend from app_private.campaign_spend_entries where id=(p_input->>'spend_entry_id')::uuid;if spend.id is null then raise exception'NOT_FOUND';end if;resource:=spend.id;select coalesce(max(version),1)into v from app_private.campaign_spend_revisions where spend_entry_id=spend.id;if expected is distinct from v then raise exception'VERSION_CONFLICT';end if;
   if spend.expense_id is not null and amount>(select amount_minor from finance_private.expenses where id=spend.expense_id)then raise exception'VALIDATION_ERROR';end if;v:=v+1;
   insert into app_private.campaign_spend_revisions(spend_entry_id,version,amount_minor,evidence_file_id,reason,actor_id)values(spend.id,v,amount,evidence,p_input->>'reason',actor);
  end if;
 end if;
 return app_private.booking_finish(ctx,resource,v,'{}'::jsonb,'analytics_recorded',jsonb_build_object('resource_id',resource));
end$$;

create function app_private.analytics_attendance(p_as_of timestamptz)returns table(learner_id uuid,occurrence_id uuid,actual_start_at timestamptz,actual_end_at timestamptz,tutor_id uuid,attendance text,attended_seconds bigint)language sql stable security definer set search_path='' as $$
 select e.learner_id,c.occurrence_id,coalesce((am.new_facts->>'actual_start_at')::timestamptz,a.actual_start_at),coalesce((am.new_facts->>'actual_end_at')::timestamptz,a.actual_end_at),ta.tutor_id,fact->>'attendance',(fact->>'attended_seconds')::bigint
 from app_private.completions c join app_private.completion_approvals approved on approved.completion_id=c.id and approved.approved_at<=p_as_of join app_private.attendance_snapshots a on a.id=c.attendance_id join app_private.tutor_assignments ta on ta.id=c.assignment_id
 left join lateral(select x.new_facts from app_private.completion_amendments x where x.completion_id=c.id and x.created_at<=p_as_of order by x.version desc limit 1)am on true
 cross join lateral jsonb_array_elements(coalesce(am.new_facts->'attendance_corrections',a.entries))fact join app_private.enrollments e on e.id=(fact->>'enrollment_id')::uuid
 where coalesce((am.new_facts->>'actual_end_at')::timestamptz,a.actual_end_at)<=p_as_of
$$;
create function app_private.analytics_cohort_rows(p_from date,p_to date,p_as_of timestamptz,p_days integer,p_campaign uuid,p_source text,p_format text,p_subject uuid)returns setof jsonb language sql stable security definer set search_path='' as $$
 with first_touch as(
  select distinct on(l.learner_id) l.learner_id,i.*,coalesce(r.attribution,'unknown')attribution,r.campaign_id
  from app_private.learner_links l join app_private.lead_inquiries i on i.id=l.inquiry_id
  left join lateral(select a.attribution,a.campaign_id from app_private.attribution_revisions a where a.inquiry_id=i.id and a.created_at<=p_as_of order by a.version desc limit 1)r on true
  where l.created_at<=p_as_of and i.recorded_at<=p_as_of and i.observed_at<=p_as_of order by l.learner_id,i.observed_at,i.id
 ),cohort as(select f.*,f.observed_at+make_interval(days=>p_days)window_end from first_touch f where(f.observed_at at time zone'Africa/Cairo')::date between p_from and p_to and(p_campaign is null or f.campaign_id=p_campaign)and(p_source is null or f.attribution=p_source)),
 facts as(select c.*,p.display_name,coalesce(h.history_complete,false)history_complete,coalesce(h.version,1)history_version,att.actual_start_at first_attendance_at,att.occurrence_id first_occurrence_id,
  (select count(*)from app_private.learner_links ll join app_private.lead_inquiries ii on ii.id=ll.inquiry_id where ll.learner_id=c.learner_id and ll.created_at<=p_as_of and ii.recorded_at<=p_as_of and ii.observed_at>=c.observed_at and ii.observed_at<least(c.window_end,p_as_of+interval'1 microsecond'))interactions,
  exists(select 1 from app_private.enrollments e join app_private.occurrences o on o.id=e.occurrence_id join app_private.offers offer on offer.id=o.offer_id join app_private.quote_acceptances q on q.learner_id=e.learner_id join app_private.quotes quote on quote.id=q.quote_id and quote.enrollment_id=e.id where e.learner_id=c.learner_id and q.accepted_at>=c.observed_at and q.accepted_at<c.window_end and q.accepted_at<=p_as_of and(p_format is null or o.format=p_format)and(p_subject is null or offer.subject_id=p_subject))booked,
  exists(select 1 from finance_private.payment_allocations pa join finance_private.charges ch on ch.id=pa.charge_id left join app_private.enrollments e on e.id=ch.enrollment_id left join app_private.occurrences o on o.id=e.occurrence_id left join app_private.offers offer on offer.id=o.offer_id where ch.learner_id=c.learner_id and pa.recorded_at<=p_as_of and pa.effective_at>=c.observed_at and pa.effective_at<c.window_end and pa.effective_at<=p_as_of and pa.amount_minor>coalesce((select sum(ar.amount_minor)from finance_private.allocation_reversals ar where ar.allocation_id=pa.id and ar.recorded_at<=p_as_of),0)and(p_format is null or o.format=p_format)and(p_subject is null or offer.subject_id=p_subject))paid,
  exists(select 1 from app_private.analytics_attendance(p_as_of)a join app_private.occurrences o on o.id=a.occurrence_id join app_private.offers offer on offer.id=o.offer_id where a.learner_id=c.learner_id and a.attendance='present'and a.attended_seconds>0 and a.actual_start_at>=c.observed_at and a.actual_start_at<c.window_end and(p_format is null or o.format=p_format)and(p_subject is null or offer.subject_id=p_subject))attended
 from cohort c join app_private.learners l on l.id=c.learner_id join app_private.people p on p.id=l.person_id
 left join lateral(select history_complete,version from app_private.learner_history_reviews h where h.learner_id=c.learner_id and h.created_at<=p_as_of order by h.version desc limit 1)h on true
 left join lateral(select a.actual_start_at,a.occurrence_id from app_private.analytics_attendance(p_as_of)a where a.learner_id=c.learner_id and a.attendance='present'and a.attended_seconds>0 order by a.actual_start_at,a.occurrence_id limit 1)att on true)
 select jsonb_build_object('learner_id',learner_id,'learner_name',display_name,'first_inquiry_id',id,'first_inquiry_at',observed_at,'cohort_date',(observed_at at time zone'Africa/Cairo')::date,'attribution',attribution,'campaign_id',campaign_id,'history_version',history_version,'history_status',case when first_attendance_at<observed_at then'returning'when history_complete then'complete'else'unknown'end,'interactions',interactions,'booked',booked,'paid',paid,'attended',attended,'newly_taught',history_complete and coalesce(first_attendance_at>=observed_at and first_attendance_at<window_end,false)and attended,'first_attendance_at',first_attendance_at,'first_occurrence_id',first_occurrence_id,'provisional',window_end>p_as_of,'window_end',window_end)from facts
$$;

create function api.get_cohort_report(p_from date,p_to date,p_as_of timestamptz,p_observation_days integer default 30,p_campaign_id uuid default null,p_source text default null,p_format text default null,p_subject_id uuid default null,p_policy_version text default'first_eligible_v1',p_cursor uuid default null,p_limit integer default 25)returns jsonb language plpgsql security definer set search_path='' as $$
declare actor uuid:=app_private.require_actor();rows jsonb;items jsonb;summary jsonb;spends jsonb;amount numeric;covered integer;spend_state text;unlinked bigint;begin
 perform app_private.require_role(actor,'admin');perform finance_private.finance_report_range(p_from,p_to,p_as_of);
 if p_to-p_from>365 or p_observation_days is null or p_observation_days not between 1 and 365 or p_limit is null or p_limit not between 1 and 100 or p_policy_version is distinct from'first_eligible_v1'or(p_source is not null and p_source not in('unknown','verified_campaign','verified_organic'))or(p_format is not null and p_format not in('private','group'))then raise exception'VALIDATION_ERROR';end if;
 select coalesce(jsonb_agg(r order by r->>'learner_id'),'[]')into rows from app_private.analytics_cohort_rows(p_from,p_to,p_as_of,p_observation_days,p_campaign_id,p_source,p_format,p_subject_id)r;
 select jsonb_build_object('learners',count(*),'interactions',coalesce(sum((r->>'interactions')::bigint),0),'booked',count(*)filter(where(r->>'booked')::boolean),'paid',count(*)filter(where(r->>'paid')::boolean),'attended',count(*)filter(where(r->>'attended')::boolean),'newly_taught',count(*)filter(where(r->>'newly_taught')::boolean),'returning',count(*)filter(where r->>'history_status'='returning'),'unknown_history',count(*)filter(where r->>'history_status'='unknown'),'verified_campaign',count(*)filter(where r->>'attribution'='verified_campaign'),'verified_organic',count(*)filter(where r->>'attribution'='verified_organic'),'unknown_source',count(*)filter(where r->>'attribution'='unknown'),'provisional',count(*)filter(where(r->>'provisional')::boolean))into summary from jsonb_array_elements(rows)r;
 select coalesce(jsonb_agg(x.r order by x.r->>'learner_id'),'[]')into items from(select r from jsonb_array_elements(rows)r where p_cursor is null or(r->>'learner_id')::uuid>p_cursor order by r->>'learner_id'limit p_limit)x;
 select count(*)into unlinked from app_private.lead_inquiries i where i.recorded_at<=p_as_of and(i.observed_at at time zone'Africa/Cairo')::date between p_from and p_to and not exists(select 1 from app_private.learner_links l where l.inquiry_id=i.id and l.created_at<=p_as_of);
 spends:='[]';amount:=null;spend_state:='not_applicable';
 if p_campaign_id is not null then
  select coalesce(jsonb_agg(jsonb_build_object('spend_entry_id',s.id,'from',s.from_date,'to',s.to_date,'amount_minor',coalesce(r.amount_minor,s.amount_minor),'expense_id',s.expense_id,'version',coalesce(r.version,1),'evidence_file_id',coalesce(r.evidence_file_id,s.evidence_file_id))order by s.from_date,s.id),'[]'),sum(coalesce(r.amount_minor,s.amount_minor)),coalesce(sum(s.to_date-s.from_date+1),0)into spends,amount,covered
  from app_private.campaign_spend_entries s left join lateral(select amount_minor,version,evidence_file_id from app_private.campaign_spend_revisions r where r.spend_entry_id=s.id and r.created_at<=p_as_of order by version desc limit 1)r on true where s.campaign_id=p_campaign_id and s.created_at<=p_as_of and s.from_date>=p_from and s.to_date<=p_to;
  if jsonb_array_length(spends)>1000 then raise exception'VALIDATION_ERROR';end if;
  spend_state:=case when covered=0 then'missing'when covered=p_to-p_from+1 then'known'else'partial'end;
 end if;
 return jsonb_build_object('from',p_from,'to',p_to,'as_of',p_as_of,'observation_days',p_observation_days,'time_zone','Africa/Cairo','policy_version',p_policy_version,'grain','learner','summary',summary,'unlinked_inquiries',unlinked,'items',items,'next_cursor',case when jsonb_array_length(items)=p_limit then items->-1->>'learner_id'else null end,'spend',jsonb_build_object('state',spend_state,'amount_minor',case when amount is null then null else finance_private.finance_safe_total(amount)end,'currency','EGP','basis','campaign_calendar_dates','cac_minor',case when spend_state='known'and(summary->>'newly_taught')::bigint>0 and p_format is null and p_subject_id is null and(p_source is null or p_source='verified_campaign')then finance_private.finance_safe_total(round(amount/(summary->>'newly_taught')::numeric))else null end,'entries',spends));
end$$;

create function api.list_campaigns(p_cursor uuid default null,p_limit integer default 25)returns jsonb language plpgsql security definer set search_path='' as $$declare actor uuid:=app_private.require_actor();items jsonb;begin perform app_private.require_role(actor,'admin');if p_limit is null or p_limit not between 1 and 100 then raise exception'VALIDATION_ERROR';end if;select coalesce(jsonb_agg(x.item order by x.id),'[]')into items from(select c.id,jsonb_build_object('campaign_id',id,'source',source,'external_campaign_id',external_campaign_id,'name',name,'active_from',active_from,'active_to',active_to)item from app_private.campaigns c where p_cursor is null or id>p_cursor order by id limit p_limit)x;return jsonb_build_object('items',items,'next_cursor',case when jsonb_array_length(items)=p_limit then items->-1->>'campaign_id'else null end);end$$;
create function api.list_analytics_inquiries(p_learner_id uuid default null,p_cursor uuid default null,p_limit integer default 25)returns jsonb language plpgsql security definer set search_path='' as $$declare actor uuid:=app_private.require_actor();items jsonb;begin perform app_private.require_role(actor,'admin');if p_limit is null or p_limit not between 1 and 100 then raise exception'VALIDATION_ERROR';end if;
 select coalesce(jsonb_agg(x.item order by x.id),'[]')into items from(select i.id,jsonb_build_object('inquiry_id',i.id,'source',i.source,'source_event_id',i.source_event_id,'actor_account_id',i.actor_account_id,'observed_at',i.observed_at,'recorded_at',i.recorded_at,'observed_source_token',i.observed_source_token,'attribution',coalesce(r.attribution,'unknown'),'campaign_id',r.campaign_id,'version',coalesce(r.version,1),'learner_ids',(select coalesce(jsonb_agg(l.learner_id order by l.learner_id),'[]')from app_private.learner_links l where l.inquiry_id=i.id))item from app_private.lead_inquiries i left join lateral(select a.*from app_private.attribution_revisions a where a.inquiry_id=i.id order by version desc limit 1)r on true where(p_cursor is null or i.id>p_cursor)and(p_learner_id is null or exists(select 1 from app_private.learner_links l where l.inquiry_id=i.id and l.learner_id=p_learner_id))order by i.id limit p_limit)x;
 return jsonb_build_object('items',items,'next_cursor',case when jsonb_array_length(items)=p_limit then items->-1->>'inquiry_id'else null end);end$$;

create function api.audit_cohort_export(p_filters jsonb,p_row_count integer,p_newly_taught_count integer)returns jsonb language plpgsql security definer set search_path='' as $$declare actor uuid:=app_private.require_actor();audit uuid;expected_count integer;expected_taught integer;begin
 perform app_private.require_role(actor,'admin');if jsonb_typeof(p_filters)is distinct from'object'or p_filters-array['from','to','as_of','observation_days','campaign_id','source','format','subject_id']<>'{}'then raise exception'VALIDATION_ERROR';end if;
 perform finance_private.finance_report_range((p_filters->>'from')::date,(p_filters->>'to')::date,(p_filters->>'as_of')::timestamptz);
 select count(*),count(*)filter(where(r->>'newly_taught')::boolean)into expected_count,expected_taught from app_private.analytics_cohort_rows((p_filters->>'from')::date,(p_filters->>'to')::date,(p_filters->>'as_of')::timestamptz,(p_filters->>'observation_days')::integer,(p_filters->>'campaign_id')::uuid,p_filters->>'source',p_filters->>'format',(p_filters->>'subject_id')::uuid)r;
 if p_row_count is distinct from expected_count or p_newly_taught_count is distinct from expected_taught then raise exception'STATE_CONFLICT';end if;
 insert into app_private.analytics_export_audits(actor_id,filters,row_count,newly_taught_count)values(actor,p_filters,p_row_count,p_newly_taught_count)returning id into audit;return jsonb_build_object('audit_id',audit);
end$$;

create function api.get_workload_report(p_from date,p_to date)returns jsonb language plpgsql security definer set search_path='' as $$
declare actor uuid:=app_private.require_actor();is_admin boolean:=app_private.has_role(actor,'admin');from_at timestamptz;to_at timestamptz;tutors jsonb:='[]';conversations jsonb:='[]';summary jsonb;begin
 if not is_admin and not app_private.has_role(actor,'customer_service')then raise exception'FORBIDDEN';end if;
 select period_start,period_end into from_at,to_at from finance_private.finance_report_range(p_from,p_to,now());if p_to-p_from>93 then raise exception'VALIDATION_ERROR';end if;
 if is_admin then
  with delivered as(select distinct occurrence_id,tutor_id,actual_start_at,actual_end_at from app_private.analytics_attendance(now())),
  occurrence_times as(select o.id,o.tutor_id,o.start_at,case when o.state<>'cancelled'and o.start_at>=from_at and o.start_at<to_at then extract(epoch from o.end_at-o.start_at)::bigint else 0 end scheduled_seconds,case when d.actual_start_at>=from_at and d.actual_start_at<to_at then extract(epoch from d.actual_end_at-d.actual_start_at)::bigint else 0 end delivered_seconds from app_private.occurrences o left join delivered d on d.occurrence_id=o.id where(o.start_at>=from_at and o.start_at<to_at)or(d.actual_start_at>=from_at and d.actual_start_at<to_at)),
  capacity as(select t.id,case when ar.id is null then null else coalesce((select sum(extract(epoch from((day::date+(i->>'end_local')::time)at time zone'Africa/Cairo')-((day::date+(i->>'start_local')::time)at time zone'Africa/Cairo')))from generate_series(p_from::timestamp,p_to::timestamp,interval'1 day')day left join app_private.availability_exceptions ex on ex.tutor_id=t.id and ex.local_date=day::date cross join lateral jsonb_array_elements(coalesce(ex.intervals,(select coalesce(jsonb_agg(w),'[]')from jsonb_array_elements(ar.weekly_intervals)w where(w->>'weekday')::integer=extract(isodow from day))))i),0)::bigint end seconds from app_private.tutors t left join app_private.availability_rules ar on ar.tutor_id=t.id)
  select coalesce(jsonb_agg(jsonb_build_object('tutor_id',t.id,'tutor_name',p.display_name,'scheduled_seconds',coalesce((select sum(o.scheduled_seconds)from occurrence_times o where o.tutor_id=t.id),0),'delivered_seconds',coalesce((select sum(o.delivered_seconds)from occurrence_times o where o.tutor_id=t.id),0),'available_seconds',cap.seconds,'capacity_state',case when cap.seconds is null then'unknown'else'configured'end,'occurrences',(select coalesce(jsonb_agg(jsonb_build_object('occurrence_id',o.id,'start_at',o.start_at,'scheduled_seconds',o.scheduled_seconds,'delivered_seconds',o.delivered_seconds)order by o.start_at,o.id),'[]')from occurrence_times o where o.tutor_id=t.id))order by t.id),'[]')into tutors from app_private.tutors t join app_private.accounts a on a.id=t.account_id join app_private.people p on p.id=a.person_id join capacity cap on cap.id=t.id;
 end if;
 with ownership as(select h.*,lead(h.created_at,1,now())over(partition by h.conversation_id order by h.created_at,h.id)ended_at from app_private.support_ownership_history h),
 response as(select c.id,first_incoming.created_at incoming_at,first_reply.created_at reply_at from app_private.conversations c left join lateral(select created_at from app_private.support_messages m where m.conversation_id=c.id and m.author='customer'order by m.created_at,m.sequence limit 1)first_incoming on true left join lateral(select created_at from app_private.support_messages m where m.conversation_id=c.id and m.author='staff'and m.created_at>=first_incoming.created_at and(is_admin or m.actor_account_id=actor)order by m.created_at,m.sequence limit 1)first_reply on true)
 select coalesce(jsonb_agg(jsonb_build_object('conversation_id',c.id,'channel',c.channel,'state',c.state,'owner_id',c.owner_account_id,'owner_name',p.display_name,'waiting_seconds',case when c.waiting_since is null or c.state='resolved'then null else greatest(0,floor(extract(epoch from now()-c.waiting_since)))end,'first_response_seconds',case when r.reply_at is null then null else greatest(0,floor(extract(epoch from r.reply_at-r.incoming_at)))end,'owned_seconds',(select coalesce(sum(greatest(0,floor(extract(epoch from least(h.ended_at,to_at,now())-greatest(h.created_at,from_at))))),0)from ownership h where h.conversation_id=c.id and h.new_owner_id is not null and(is_admin or h.new_owner_id=actor)),'ownership_changes',(select count(*)from ownership h where h.conversation_id=c.id and h.created_at>=from_at and h.created_at<to_at and(is_admin or h.new_owner_id=actor or h.previous_owner_id=actor)))order by c.id),'[]')into conversations from app_private.conversations c left join app_private.accounts a on a.id=c.owner_account_id left join app_private.people p on p.id=a.person_id left join response r on r.id=c.id where(c.created_at>=from_at and c.created_at<to_at or c.state in('waiting','assigned','escalated')or exists(select 1 from app_private.support_messages m where m.conversation_id=c.id and m.created_at>=from_at and m.created_at<to_at))and(is_admin or c.owner_account_id=actor);
 if jsonb_array_length(tutors)>500 or jsonb_array_length(conversations)>5000 then raise exception'VALIDATION_ERROR';end if;
 summary:=jsonb_build_object('scheduled_seconds',(select coalesce(sum((r->>'scheduled_seconds')::bigint),0)from jsonb_array_elements(tutors)r),'delivered_seconds',(select coalesce(sum((r->>'delivered_seconds')::bigint),0)from jsonb_array_elements(tutors)r),'open_conversations',(select count(*)from jsonb_array_elements(conversations)r where r->>'state'not in('resolved','bot')),'unassigned_conversations',(select count(*)from jsonb_array_elements(conversations)r where r->>'state'not in('resolved','bot')and r->>'owner_id'is null),'answered_conversations',(select count(*)from jsonb_array_elements(conversations)r where r->>'first_response_seconds'is not null),'total_response_seconds',(select coalesce(sum((r->>'first_response_seconds')::bigint),0)from jsonb_array_elements(conversations)r),'total_owned_seconds',(select coalesce(sum((r->>'owned_seconds')::bigint),0)from jsonb_array_elements(conversations)r));
 return jsonb_build_object('from',p_from,'to',p_to,'time_zone','Africa/Cairo','staffed_hours_state','unknown','staffed_response_seconds',null,'tutors',tutors,'conversations',conversations,'summary',summary,'next_cursor',null);
end$$;

-- Preserve real retained observations when adding analytics to an existing installation.
do $$declare r record;begin
 for r in select e.*from app_private.enrollments e loop perform app_private.analytics_record_inquiry('website_booking',r.id,null,r.booker_account_id,r.created_at,null,r.learner_id);end loop;
 for r in select m.id,m.created_at,c.id conversation_id,c.channel,c.account_id,c.source_token,l.id learner_id from app_private.support_messages m join app_private.conversations c on c.id=m.conversation_id left join app_private.learners l on l.account_id=c.account_id where m.author='customer'loop perform app_private.analytics_record_inquiry(case when r.channel='whatsapp'then'whatsapp'else'support'end,r.id,r.conversation_id,r.account_id,r.created_at,r.source_token,r.learner_id);end loop;
end$$;
insert into app_private.learner_links(inquiry_id,learner_id,basis,actor_id)select i.id,s.learner_id,'verified_support_link',s.account_id from app_private.lead_inquiries i join app_private.support_account_links s on s.conversation_id=i.conversation_id where s.learner_id is not null on conflict do nothing;

alter function app_private.file_resolve_target(uuid,text,text,uuid)rename to file_resolve_target_pre_analytics;
create function app_private.file_resolve_target(p_actor uuid,p_purpose text,p_action text,p_target uuid)returns jsonb language plpgsql security definer set search_path='' as $$begin
 if p_purpose='review_evidence'and p_action='analytics_evidence'then perform app_private.require_role(p_actor,'admin');if p_target is not null then raise exception'VALIDATION_ERROR';end if;return jsonb_build_object('internal_purpose','analytics_evidence','parent_type','analytics','parent_id',null,'learner_id',null,'charge_id',null);end if;
 return app_private.file_resolve_target_pre_analytics(p_actor,p_purpose,p_action,p_target);
end$$;
alter function api.list_payment_evidence(text,uuid,text,integer)rename to list_payment_evidence_pre_analytics;
create function api.list_payment_evidence(p_action text,p_target_id uuid,p_cursor text default null,p_limit integer default 25)returns jsonb language plpgsql security definer set search_path='' as $$declare actor uuid:=app_private.require_actor();after_at timestamptz;after_id uuid;rows jsonb;begin
 if p_action<>'analytics_evidence'then return api.list_payment_evidence_pre_analytics(p_action,p_target_id,p_cursor,p_limit);end if;
 perform app_private.file_resolve_target(actor,'review_evidence',p_action,p_target_id);if p_limit is null or p_limit not between 1 and 100 then raise exception'VALIDATION_ERROR';end if;
 if p_cursor is not null then if length(p_cursor)>200 or array_length(string_to_array(p_cursor,'|'),1)<>2 then raise exception'VALIDATION_ERROR';end if;after_at:=split_part(p_cursor,'|',1)::timestamptz;after_id:=split_part(p_cursor,'|',2)::uuid;end if;
 select coalesce(jsonb_agg(jsonb_build_object('id',x.id,'at',x.created_at,'data',app_private.payment_file_dto(x.id))order by x.created_at desc,x.id desc),'[]')into rows from(select f.*from app_private.files f where f.purpose='analytics_evidence'and f.parent_type='analytics'and f.parent_id is null and f.uploader_account_id=actor and app_private.file_is_clean(f.id)and(p_cursor is null or(f.created_at,f.id)<(after_at,after_id))order by f.created_at desc,f.id desc limit p_limit+1)x;return app_private.package_page(rows,p_limit);
end$$;

do $$declare t text;f record;begin
 foreach t in array array['lead_inquiries','learner_links','campaigns','attribution_revisions','learner_history_reviews','learner_attribution_revisions','campaign_spend_entries','campaign_spend_revisions','analytics_export_audits']loop
  execute format('alter table app_private.%I enable row level security',t);execute format('create policy commands_access on app_private.%I to git_tutor_commands using(true)with check(true)',t);execute format('revoke all on app_private.%I from public,anon,authenticated,service_role,git_tutor_worker',t);execute format('grant select,insert on app_private.%I to git_tutor_commands',t);execute format('create trigger immutable_row before update or delete on app_private.%I for each row execute function app_private.reject_immutable_change()',t);
 end loop;
 for f in select p.oid::regprocedure::text signature,n.nspname,p.proname from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname in('api','app_private')and(p.proname like'analytics_%'or p.proname=any(array['get_cohort_report','list_campaigns','list_analytics_inquiries','get_workload_report','audit_cohort_export','file_resolve_target','file_resolve_target_pre_analytics','list_payment_evidence','list_payment_evidence_pre_analytics']))loop
  execute format('alter function %s owner to git_tutor_commands',f.signature);execute format('revoke all on function %s from public,anon,authenticated,service_role,git_tutor_worker',f.signature);if f.nspname='api'and f.proname<>'list_payment_evidence_pre_analytics'then execute format('grant execute on function %s to authenticated',f.signature);end if;
 end loop;
end$$;
revoke create on schema api,app_private from git_tutor_commands;
